<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Http\Request;
class CcsInvoiceCancellation{
public function cancel(Request $r,int $id):array{
$rules=app(CcsHumanRules::class);abort_unless(in_array(app(CcsAdministration::class)->role($r->user()),['owner','cashier'],true),403);$d=$r->validate(['reason'=>'required|string|min:5|max:1000','confirmation'=>'required|accepted','goods_returned'=>'nullable|boolean','refund_confirmed'=>'nullable|accepted','request_token'=>'required|uuid']);
$prior=DB::table('ccs_invoice_cancellations')->where('invoice_id',$id)->first();if($prior)return ['refund_lkr'=>(float)$prior->refund_lkr,'duplicate'=>true];$approval=$rules->approve($r,'invoice_cancel',['invoice_id'=>$id,'reason'=>$d['reason'],'goods_returned'=>$r->boolean('goods_returned'),'refund_confirmed'=>$r->boolean('refund_confirmed')]);return DB::transaction(function()use($r,$id,$rules,$d,$approval){$rules->lock();$invoice=DB::table('invoices')->where('id',$id)->lockForUpdate()->first();abort_unless($invoice,404);$prior=DB::table('ccs_invoice_cancellations')->where('invoice_id',$id)->first();if($prior)return ['refund_lkr'=>(float)$prior->refund_lkr,'duplicate'=>true];if($invoice->status==='void')$rules->fail('reason','This invoice was already voided.');if(DB::table('ccs_invoice_cancellations')->where('request_token',$d['request_token'])->exists())$rules->fail('reason','Cancellation token belongs to another invoice. Reload.');
$paid=DB::table('payments')->where('invoice_id',$id)->get()->sum(fn($p)=>(int)round((float)$p->amount_lkr*100));if($paid>0&&!$r->boolean('refund_confirmed'))$rules->fail('refund_confirmed','Confirm the refund has actually been given before recording it. No money is sent automatically.');
$draft=$invoice->status==='draft';$returned=$draft||$r->boolean('goods_returned');if($returned){foreach(DB::table('invoice_items')->where('invoice_id',$id)->where('stock_managed',true)->orderBy('inventory_item_id')->get() as $line){$part=DB::table('inventory_items')->where('id',$line->inventory_item_id)->lockForUpdate()->first();if(!$part)$rules->fail('reason','Stock part is missing; cancellation stopped.');if($line->stock_unit_id){$n=DB::table('stock_units')->where('id',$line->stock_unit_id)->where('invoice_id',$id)->whereIn('status',['reserved','sold'])->update(['status'=>'available','invoice_id'=>null,'updated_at'=>now()]);if($n!==1)$rules->fail('reason','Serial has changed; cancellation stopped without changing stock.');}DB::table('inventory_items')->where('id',$part->id)->increment('quantity_on_hand',(int)$line->quantity,['updated_at'=>now()]);DB::table('stock_movements')->insert(['inventory_item_id'=>$part->id,'repair_job_id'=>$invoice->repair_job_id,'recorded_by'=>$r->user()->id,'quantity_change'=>(int)$line->quantity,'reason'=>'invoice_void_return','notes'=>mb_substr('Invoice '.$invoice->invoice_number.': '.$d['reason'],0,1000),'created_at'=>now(),'updated_at'=>now()]);}}
if($paid>0)DB::table('payments')->insert(['invoice_id'=>$id,'amount_lkr'=>number_format(-$paid/100,2,'.',''),'method'=>'other','reference'=>mb_substr('Full void/refund: '.$d['reason'],0,100),'request_token'=>$d['request_token'],'received_by_user_id'=>$r->user()->id,'paid_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);
foreach(DB::table('warranties')->where('repair_job_id',$invoice->repair_job_id)->get() as $w){$terms=json_decode($w->terms_snapshot,true)??[];if($w->invoice_item_id&&!DB::table('invoice_items')->where('id',$w->invoice_item_id)->where('invoice_id',$id)->exists())continue;$terms['revoked']=true;$terms['provisional']=true;$terms['approval_pending_reason']='Invoice voided: '.$invoice->invoice_number;DB::table('warranties')->where('id',$w->id)->update(['terms_snapshot'=>json_encode($terms,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);}
DB::table('invoices')->where('id',$id)->update(['status'=>'void','updated_at'=>now()]);DB::table('ccs_invoice_cancellations')->insert(['invoice_id'=>$id,'recorded_by'=>$r->user()->id,'reason'=>$d['reason'],'refund_lkr'=>$paid/100,'goods_returned'=>$returned,'request_token'=>$d['request_token'],'invoice_snapshot'=>json_encode($invoice),'created_at'=>now(),'updated_at'=>now()]);$rules->consume($approval,$r->user()->id);app(CcsAdministration::class)->audit($r->user()->id,'invoice_void_refund','invoice',$id,['reason'=>$d['reason'],'refunded'=>$paid/100,'stock_returned'=>$returned]);return ['refund_lkr'=>$paid/100,'duplicate'=>false];},3);
}
}
